begin;
do $$ declare ownerid uuid;otherid uuid;c uuid;f uuid;f2 uuid;i uuid;q jsonb;denied boolean;begin
 select s.customer_id into ownerid from public.customer_subscriptions s join public.store_products p on p.id=s.product_id where p.service_code='crm' and s.starts_at<=now() and s.expires_at>now() limit 1;
 select id into otherid from public.profiles where id<>ownerid and role<>'admin' limit 1;
 if ownerid is null or otherid is null then raise exception 'test accounts needed';end if;
 perform set_config('request.jwt.claim.sub',ownerid::text,true);execute 'set local role authenticated';
 insert into public.crm_customers(tenant_id,name) values(ownerid,'آزمون تکمیل اطلاعات') returning id into c;
 insert into public.crm_field_definitions(tenant_id,key,label,type,priority,question) values(ownerid,'test-'||c,'تولد آزمون','birthday',100,'روز و ماه تولد؟') returning id into f;
 insert into public.crm_field_definitions(tenant_id,key,label,type,priority,question,condition) values(ownerid,'test-second-'||c,'نیاز آزمون','text',99,'نیاز بعدی؟','after_purchase') returning id into f2;
 q=public.crm_information_queue(500);
 if not exists(select 1 from jsonb_array_elements(q) x where x->>'customer_id'=c::text and x->>'field_id'=f::text) then raise exception 'priority queue';end if;
 perform public.crm_information_action(c,f,'asked');
 if exists(select 1 from jsonb_array_elements(public.crm_information_queue(500)) x where x->>'customer_id'=c::text) then raise exception 'question cooldown';end if;
 perform public.crm_information_action(c,f,'reset');
 insert into public.crm_interactions(tenant_id,customer_id,direction,body) values(ownerid,c,'inbound','تولد آزمون: ۰۳/۱۵') returning id into i;
 if not exists(select 1 from public.crm_customers where id=c and custom_fields->>('test-'||c)='03/15') then raise exception 'explicit extraction and digit normalization';end if;
 if not exists(select 1 from public.crm_information_states where customer_id=c and field_id=f and status='confirmed' and source_interaction_id=i and source='explicit_message') then raise exception 'provenance';end if;
 insert into public.crm_interactions(tenant_id,customer_id,direction,body) values(ownerid,c,'inbound','تولد آزمون: ۰۴/۱۵');
 if not exists(select 1 from public.crm_customers where id=c and custom_fields->>('test-'||c)='03/15') or not exists(select 1 from public.crm_information_states where customer_id=c and field_id=f and status='review' and proposed_value='"04/15"'::jsonb) then raise exception 'conflict must not overwrite';end if;
 perform public.crm_resolve_information(c,f,false);
 if exists(select 1 from public.crm_information_states where customer_id=c and field_id=f and status='review') then raise exception 'review dismissal';end if;
 insert into public.crm_interactions(tenant_id,customer_id,direction,body) values(ownerid,c,'inbound','تولد آزمون: ۰۵/۱۰');
 perform public.crm_resolve_information(c,f,true);
 if not exists(select 1 from public.crm_customers where id=c and custom_fields->>('test-'||c)='05/10') or not exists(select 1 from public.crm_information_states where customer_id=c and field_id=f and status='confirmed' and source='explicit_message') then raise exception 'review acceptance';end if;
 denied=false;begin update public.crm_customers set custom_fields=jsonb_build_object('test-'||c,'13/40') where id=c;exception when others then denied=true;end;if not denied then raise exception 'invalid birthday accepted';end if;
 insert into public.crm_orders(tenant_id,customer_id,reference,amount,status) values(ownerid,c,'information-'||c,1000,'paid');
 if not exists(select 1 from jsonb_array_elements(public.crm_information_queue(500)) x where x->>'customer_id'=c::text and x->>'field_id'=f2::text) then raise exception 'purchase eligibility';end if;
 perform public.crm_information_action(c,f2,'declined');
 if exists(select 1 from jsonb_array_elements(public.crm_information_queue(500)) x where x->>'customer_id'=c::text and x->>'field_id'=f2::text) then raise exception 'declined question';end if;
 perform public.crm_information_action(c,f2,'reset');
 insert into public.crm_interactions(tenant_id,customer_id,direction,body) values(ownerid,c,'inbound','فوری نیاز دارم');
 if exists(select 1 from jsonb_array_elements(public.crm_information_queue(500)) x where x->>'customer_id'=c::text) then raise exception 'urgent interaction suppression';end if;
 denied=false;begin insert into public.crm_information_states(tenant_id,customer_id,field_id,status) values(otherid,c,f,'confirmed');exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'cross tenant write';end if;
 perform set_config('request.jwt.claim.sub',otherid::text,true);
 if exists(select 1 from public.crm_information_states where customer_id=c) or exists(select 1 from public.crm_field_definitions where id=f) then raise exception 'cross tenant read';end if;
 execute 'reset role';
end $$;
select 'PASS: priority, contextual eligibility, cooldown, optout, explicit extraction, provenance, conflict review, validation and tenant isolation' result;
rollback;
